// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public {
        c = new ModifierEntrancy();
    }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max);
        Bank bank = new Bank();
        address caller = address(bank);
        // caller has zero balance and its supportsToken() matches, so airDrop
        // must succeed and credit it 20 tokens
        vm.prank(caller);
        try c.airDrop() {
            assertTrue(c.tokenBalance(caller) == 20, "airDrop must credit 20 tokens");
        } catch {
            assertTrue(false, "airDrop must succeed for a fresh eligible caller");
        }
    }
}
